const ai = $input.first().json;

// Parse AI response
let rawContent;
try {
  const raw = ai.message?.content || ai.text || ai.output || '';
  rawContent = typeof raw === 'string' ? JSON.parse(raw) : raw || {};
} catch (e) {
  console.log('Parse error:', e);
  rawContent = {};
}

// Extract content and image prompt
const content = {
  facebook: (rawContent.facebook ?? rawContent.Facebook ?? '').trim(),
  instagram: (rawContent.instagram ?? rawContent.Instagram ?? '').trim()
};

const imagePrompt = rawContent.image_prompt || rawContent.imagePrompt || 
  'Professional social media post image, modern design, vibrant colors';

// Build platforms automatically
const platforms = Object.entries(content)
  .filter(([_, text]) => text.length > 0)
  .map(([platform]) => platform);

return [{
  json: {
    platforms,
    content,
    image_prompt: imagePrompt,
    status: 'draft'
  }
}];

// Handle DALL-E response - check for binary data OR URL
const dalleResponse = $input.first().json;
const binaryData = $input.first().binary;
const previousData = $('Parse AI Response').first().json;

console.log('=== DALL-E Response Debug ===');
console.log('JSON:', JSON.stringify(dalleResponse, null, 2));
console.log('Has binary:', !!binaryData);
if (binaryData) console.log('Binary keys:', Object.keys(binaryData));

// Check if we have binary data (n8n downloaded the image)
const hasBinaryImage = binaryData && Object.keys(binaryData).length > 0;

if (hasBinaryImage) {
  console.log('Image is in binary format - will upload directly');
  // Return a special flag to indicate binary upload path
  return [{
    json: {
      has_binary_image: true,
      temp_image_url: '', // No URL, we're using binary
      platforms: previousData.platforms,
      content: previousData.content,
      status: 'draft'
    },
    binary: binaryData
  }];
}

// Fallback: try to extract URL if not binary
let tempImageUrl = '';

if (dalleResponse.data && Array.isArray(dalleResponse.data) && dalleResponse.data[0]?.url) {
  tempImageUrl = dalleResponse.data[0].url;
} else if (dalleResponse.url) {
  tempImageUrl = dalleResponse.url;
} else if (dalleResponse.images && dalleResponse.images[0]) {
  tempImageUrl = dalleResponse.images[0].url || dalleResponse.images[0];
} else if (dalleResponse.image) {
  tempImageUrl = dalleResponse.image.url || dalleResponse.image;
} else if (dalleResponse.image_url) {
  tempImageUrl = dalleResponse.image_url;
}

console.log('Final temp_image_url:', tempImageUrl || 'NOT FOUND');

return [{
  json: {
    has_binary_image: false,
    temp_image_url: tempImageUrl,
    platforms: previousData.platforms,
    content: previousData.content,
    status: 'draft'
  }
}];

// Generate a unique filename for the image
const timestamp = Date.now();
const randomId = Math.random().toString(36).substring(2, 8);
const filename = `post_${timestamp}_${randomId}.png`;

// Get the binary data - either from this node's input (binary passthrough) or from download
const binaryData = $input.first().binary;

// Get previous data from the check node
const prevData = $('Has Image URL?').first().json;

console.log('Prepare Upload - Has binary:', !!binaryData);
console.log('Prepare Upload - Binary keys:', binaryData ? Object.keys(binaryData) : 'none');

return [{
  json: {
    filename: filename,
    platforms: prevData.platforms,
    content: prevData.content,
    status: prevData.status
  },
  binary: binaryData
}];

// Construct the permanent public URL
const filename = $('Prepare Storage Upload').first().json.filename;
const prevData = $('Prepare Storage Upload').first().json;

// Supabase Storage public URL format
const permanentUrl = `https://qbppaxuhhdumnudnjwtp.supabase.co/storage/v1/object/public/post-images/${filename}`;

return [{
  json: {
    platforms: prevData.platforms,
    content: prevData.content,
    image_url: permanentUrl,
    status: prevData.status
  }
}];

// No image case - pass through with empty image_url
const prevData = $('Has Image URL?').first().json;

return [{
  json: {
    platforms: prevData.platforms,
    content: prevData.content,
    image_url: '',
    status: prevData.status
  }
}];
